import itertools, random
from test_reduce import sat_solve, vc_solve, random_sat_instance
from reduce import reduce
from problems import TARGET

# 1) Cross-check vc_solve against a naive brute force on random small graphs.
def vc_brute(inst):
    n, edges, k = inst["n"], inst["edges"], inst["k"]
    if k < 0: return False
    if k >= n: return True
    for size in range(k+1):
        for sub in itertools.combinations(range(n), size):
            s = set(sub)
            if all(u in s or v in s for u, v in edges):
                return True
    return False

rng = random.Random(7)
mismatch = 0
for _ in range(3000):
    n = rng.randint(0, 7)
    allp = [(u, v) for u in range(n) for v in range(u+1, n)]
    rng.shuffle(allp)
    edges = [list(e) for e in allp[:rng.randint(0, len(allp))]]
    k = rng.randint(-1, n+1)
    inst = {"n": n, "edges": edges, "k": k}
    TARGET.validate(inst)
    if vc_solve(inst) != vc_brute(inst):
        mismatch += 1
print("vc solver cross-check mismatches:", mismatch)

# 2) Exhaustive small 3-SAT formulas, m=3, c in 0..2 (all clause choices).
clauses_pool = []
for vs in itertools.permutations([1,2,3]):
    for signs in itertools.product([1,-1], repeat=3):
        clauses_pool.append([s*v for s,v in zip(signs, vs)])
clauses_pool = [list(c) for c in {tuple(c) for c in clauses_pool}]
print("pool size:", len(clauses_pool))

bad = 0
count = 0
for c in range(0, 3):
    for combo in itertools.combinations_with_replacement(clauses_pool, c):
        inst = {"num_vars": 3, "clauses": [list(x) for x in combo]}
        count += 1
        red = reduce(inst)
        if sat_solve(inst) != vc_solve(red):
            bad += 1
            if bad <= 5: print("BAD", inst, red)
print("exhaustive m=3 c<=2:", count, "bad:", bad)

# 3) Larger random formulas (m up to 6, c up to 12) to stress both directions.
bad2 = 0
for _ in range(2000):
    inst = random_sat_instance(rng, max_vars=6, max_clauses=12)
    red = reduce(inst)
    if sat_solve(inst) != vc_solve(red):
        bad2 += 1
        if bad2 <= 5: print("BAD2", inst, red)
print("larger random bad:", bad2)

# 4) Polynomial-time / no brute force: check reduce scales and doesn't blow up.
import time
big = {"num_vars": 50, "clauses": [[1,2,3]]*200}
t=time.time(); r=reduce(big); dt=time.time()-t
print("big reduce time", round(dt,4), "n=", r["n"], "k=", r["k"], "edges=", len(r["edges"]))
EOF
